def backfill_chat_rooms(apps, schema_editor):
    """Backfill ChatRoom terstruktur dari session_id ChatMessage yang sudah ada."""
    from guest_book.models import parse_chat_session_id

    db_alias = schema_editor.connection.alias
    ChatRoom = apps.get_model('guest_book', 'ChatRoom')
    ChatMessage = apps.get_model('guest_book', 'ChatMessage')
    Tamu = apps.get_model('guest_book', 'Tamu')
    Pegawai = apps.get_model('guest_book', 'Pegawai')
    Kunjungan = apps.get_model('guest_book', 'Kunjungan')

    sessions = list(
        ChatMessage.objects.using(db_alias)
        .values('session_id')
        .annotate(last_msg=Max('created_at'))
    )
    if not sessions:
        return

    parsed_rows = []
    tamu_uuids = set()
    pegawai_uuids = set()
    kunjungan_uuids = set()
    for row in sessions:
        parsed = parse_chat_session_id(row['session_id'])
        if not parsed['session_id']:
            continue
        parsed['last_msg'] = row['last_msg']
        parsed_rows.append(parsed)
        if parsed['entity_uuid'] is not None:
            if parsed['room_type'] == 'tamu_admin':
                tamu_uuids.add(parsed['entity_uuid'])
            elif parsed['room_type'] == 'pegawai_admin':
                pegawai_uuids.add(parsed['entity_uuid'])
            elif parsed['room_type'] == 'kunjungan':
                kunjungan_uuids.add(parsed['entity_uuid'])

    valid_tamu = set(Tamu.objects.using(db_alias).filter(pk__in=tamu_uuids).values_list('id', flat=True)) if tamu_uuids else set()
    valid_pegawai = set(Pegawai.objects.using(db_alias).filter(pk__in=pegawai_uuids).values_list('id', flat=True)) if pegawai_uuids else set()
    kunj_map = (
        {
            k['id']: k
            for k in Kunjungan.objects.using(db_alias)
            .filter(pk__in=kunjungan_uuids)
            .values('id', 'tamu_id', 'pegawai_id')
        }
        if kunjungan_uuids
        else {}
    )

    for parsed in parsed_rows:
        sid = parsed['session_id']
        rtype = parsed['room_type']
        eid = parsed['entity_uuid']
        tamu_id = eid if (rtype == 'tamu_admin' and eid in valid_tamu) else None
        pegawai_id = eid if (rtype == 'pegawai_admin' and eid in valid_pegawai) else None
        kunjungan_id = None
        if rtype == 'kunjungan' and eid in kunj_map:
            kunj = kunj_map[eid]
            kunjungan_id = kunj['id']
            tamu_id = kunj['tamu_id']
            pegawai_id = kunj['pegawai_id']

        room, _ = ChatRoom.objects.using(db_alias).get_or_create(
            session_id=sid,
            defaults={
                'room_type': rtype,
                'tamu_id': tamu_id,
                'pegawai_id': pegawai_id,
                'kunjungan_id': kunjungan_id,
                'last_message_at': parsed['last_msg'],
            },
        )
        ChatMessage.objects.using(db_alias).filter(
            session_id=sid,
            room__isnull=True,
        ).update(room_id=room.id)


